import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353;

    static long powMod(long base, long exp) {
        long res = 1L;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }

    static long inverseMod(long x) {
        return powMod(x, MOD - 2);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] input = br.readLine().split(" ");
        long n = Long.parseLong(input[0]);
        long m = Long.parseLong(input[1]);
        long l = Long.parseLong(input[2]);
        long r = Long.parseLong(input[3]);

        PrintWriter pw = new PrintWriter(System.out);
        if (l == r) {
            pw.println(1);
            pw.flush();
            return;
        }

        long oddCount = ((r + 1) / 2) - (l / 2);
        long evenCount = (r / 2) - ((l - 1) / 2);
        long totalCells = n * m;

        long result;
        if (totalCells % 2 == 1) {
            result = powMod(oddCount + evenCount, totalCells);
        } else {
            long sum = (powMod(oddCount + evenCount, totalCells) + powMod(oddCount - evenCount, totalCells)) % MOD;
            result = (sum * inverseMod(2)) % MOD;
        }
        pw.println(result);
        pw.flush();
    }
}
